import pg from "pg";
import { AsyncLocalStorage } from "node:async_hooks";

const ID_TABLES = new Set([
  "users",
  "rooms",
  "messages",
  "purchases",
  "scores",
  "audit",
]);
export function postgresSQL(sql) {
  let next = sql
    .replace(
      /id INTEGER PRIMARY KEY/g,
      "id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
    )
    .replace(/expires INTEGER/g, "expires BIGINT")
    .replace(
      /DEFAULT CURRENT_TIMESTAMP/g,
      "DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')",
    )
    .replace(/\b(\w+)\s*=\s*\?\s+COLLATE NOCASE/gi, "LOWER($1)=LOWER(?)");
  const ignore = /INSERT OR IGNORE/i.test(next);
  next = next.replace(/INSERT OR IGNORE/gi, "INSERT");
  next = next.replace(
    /\b(CREATE TABLE IF NOT EXISTS|ALTER TABLE|REFERENCES|FROM|JOIN|INTO|UPDATE|ON)\s+([a-z_][a-z_0-9]*)(?![\w.])/gi,
    (match, keyword, table) =>
      keyword.toUpperCase() === "ON" && !/CREATE INDEX/i.test(next)
        ? match
        : `${keyword} pixel_playground.${table}`,
  );
  if (ignore) next = next.replace(/;?\s*$/, " ON CONFLICT DO NOTHING");
  let index = 0;
  return next.replace(/\?/g, () => `$${++index}`);
}

export function openPostgres(connectionString) {
  const url = new URL(connectionString);
  if (!["postgres:", "postgresql:"].includes(url.protocol))
    throw new Error("SUPABASE_DB_URL must be a PostgreSQL connection string.");
  const local = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
  // pg connection-string SSL options can override certificate verification.
  for (const key of ["sslmode", "sslcert", "sslkey", "sslrootcert"])
    url.searchParams.delete(key);
  const pool = new pg.Pool({
    connectionString: url.href,
    max: 3,
    idleTimeoutMillis: 10000,
    connectionTimeoutMillis: 10000,
    ssl: local
      ? false
      : {
          rejectUnauthorized: true,
          ...(process.env.SUPABASE_CA_CERT
            ? { ca: process.env.SUPABASE_CA_CERT }
            : {}),
        },
  });
  pool.on("error", (error) =>
    console.error("Database connection error:", error.code || error.name),
  );
  const context = new AsyncLocalStorage();
  const query = (sql, args = []) =>
    (context.getStore() || pool).query(sql, args);
  return {
    remote: true,
    postgres: true,
    prepare(sql) {
      const translated = postgresSQL(sql);
      return {
        async run(...args) {
          const table = sql.match(
            /^\s*INSERT(?: OR IGNORE)? INTO ([a-z_]+)/i,
          )?.[1];
          const returning =
            ID_TABLES.has(table) && !/RETURNING/i.test(translated);
          const result = await query(
            translated + (returning ? " RETURNING id" : ""),
            args,
          );
          return {
            changes: result.rowCount,
            lastInsertRowid: result.rows[0]?.id,
          };
        },
        async get(...args) {
          return (await query(translated, args)).rows[0];
        },
        async all(...args) {
          return (await query(translated, args)).rows;
        },
      };
    },
    async exec(sql) {
      await query("CREATE SCHEMA IF NOT EXISTS pixel_playground");
      for (const statement of sql.split(";").filter((value) => value.trim()))
        await query(postgresSQL(statement));
    },
    async transaction(task) {
      const client = await pool.connect();
      try {
        await client.query("BEGIN");
        // Shared lock preserves SQLite-style serialized writes across instances.
        await client.query("SELECT pg_advisory_xact_lock(1465071681)");
        const result = await context.run(client, task);
        await client.query("COMMIT");
        return result;
      } catch (error) {
        await client.query("ROLLBACK");
        throw error;
      } finally {
        client.release();
      }
    },
    close() {
      return pool.end();
    },
  };
}
